/**
 * @file templates.ts
 * Default file templates generated by the Spellbookx CLI setup.
 */

import { CONFIG_DIR, CSPELL_DICTIONARY_PATH } from '../lib/config-files.js';
import type {
  ConfigLocation,
  CSpellFormat,
  ESLintConfigId,
  PrettierConfigId,
} from '../types/index.js';

/**
 * Initial empty project word list for CSpell.
 */
export const CSPELL_CUSTOM_DICTIONARY_TEMPLATE = `# Project words for CSpell (one word per line, case-insensitive)
`;

/**
 * Returns the dictionary path as written in the CSpell config file. CSpell
 * resolves it relative to the config file.
 *
 * @param format - The selected CSpell format.
 * @param location - The selected CSpell location.
 * @returns The dictionary path relative to the config file.
 */
function cspellDictionaryPath(
  format: CSpellFormat,
  location: ConfigLocation
): string {
  return format !== 'mjs' && location === 'config-dir'
    ? `./${CSPELL_DICTIONARY_PATH.slice(CONFIG_DIR.length + 1)}`
    : `./${CSPELL_DICTIONARY_PATH}`;
}

/**
 * Builds the CSpell configuration for the selected format.
 *
 * - `yaml` and `json` import the `cspell-config-spellbookx` preset.
 * - `mjs` calls `defineSbxConfig`, which merges the overrides into the preset.
 *
 * @param format - The selected CSpell format.
 * @param location - The selected CSpell location.
 * @returns File content for the CSpell configuration.
 */
export function cspellConfigTemplate(
  format: CSpellFormat,
  location: ConfigLocation
): string {
  const dictionaryPath = cspellDictionaryPath(format, location);

  if (format === 'mjs') {
    return `import { defineSbxConfig } from 'cspell-config-spellbookx';

// Documentation: https://cspell.org/docs/Configuration
// defineSbxConfig merges these settings into the Spellbookx preset
// (languages, technical dictionaries, and shared ignore globs).
export default defineSbxConfig({
  // Project word list, one word per line. The path is relative to this file.
  dictionaryDefinitions: [
    {
      name: 'project-words',
      path: '${dictionaryPath}',
      addWords: true,
    },
  ],
  dictionaries: ['project-words'],
});
`;
  }

  if (format === 'json') {
    return `${JSON.stringify(
      {
        $schema:
          'https://raw.githubusercontent.com/streetsidesoftware/cspell/main/cspell.schema.json',
        version: '0.2',
        import: ['cspell-config-spellbookx'],
        dictionaryDefinitions: [
          { name: 'project-words', path: dictionaryPath, addWords: true },
        ],
        dictionaries: ['project-words'],
      },
      null,
      2
    )}\n`;
  }

  return `# yaml-language-server: $schema=https://raw.githubusercontent.com/streetsidesoftware/cspell/main/cspell.schema.json
# CSpell configuration
# Documentation: https://cspell.org/docs/Configuration

version: '0.2'

# Spellbookx preset: languages, technical dictionaries, and shared ignore globs.
import:
  - cspell-config-spellbookx

# Project word list, one word per line. The path is relative to this file.
dictionaryDefinitions:
  - name: project-words
    path: ${dictionaryPath}
    addWords: true

dictionaries:
  - project-words
`;
}

/**
 * Default commitlint configuration (`.config/commitlint.mjs` or
 * `commitlint.config.mjs`).
 *
 * @remarks
 * The preset extends `@commitlint/config-conventional` and enforces the
 * Spellbookx commit types, the discovered monorepo scopes, and the header,
 * body, and footer length limits.
 */
export const COMMITLINT_CONFIG_TEMPLATE = `/**
 * Commitlint configuration for Spellbookx.
 * Documentation: https://commitlint.js.org/reference/configuration
 *
 * Extends \`@commitlint/config-conventional\` and applies the Spellbookx preset:
 * the Spellbookx commit types, the discovered monorepo scopes, and the
 * header, body, and footer length limits.
 */
export { default } from 'commitlint-config-spellbookx';
`;

/**
 * Default czg configuration (`.config/cz.mjs` or `cz.config.mjs`).
 *
 * Spreads the `cz-config-spellbookx` preset into `definePrompt` from `czg`.
 */
export const CZG_CONFIG_TEMPLATE = `/**
 * czg commit prompt configuration for Spellbookx.
 * Documentation: https://cz-git.qbb.sh/config/
 */
import { config } from 'cz-config-spellbookx';
import { definePrompt } from 'czg';

export default definePrompt({
  ...config,
});
`;

